CREATE TYPE public.app_role AS ENUM ('admin','user');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE NOT NULL, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
CREATE POLICY read_own_role ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.cms_admin_allowlist (email text PRIMARY KEY);
GRANT ALL ON public.cms_admin_allowlist TO service_role;
ALTER TABLE public.cms_admin_allowlist ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.assign_cms_admin() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.email_confirmed_at IS NOT NULL AND EXISTS(SELECT 1 FROM public.cms_admin_allowlist WHERE lower(email)=lower(NEW.email)) THEN INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'admin') ON CONFLICT DO NOTHING; END IF; RETURN NEW; END $$;
CREATE TRIGGER assign_cms_admin AFTER INSERT OR UPDATE OF email_confirmed_at,email ON auth.users FOR EACH ROW EXECUTE FUNCTION public.assign_cms_admin();
CREATE TABLE public.site_content (key text PRIMARY KEY, value text NOT NULL, kind text NOT NULL CHECK(kind IN ('text','image')), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.site_content TO anon;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.site_content TO authenticated;
GRANT ALL ON public.site_content TO service_role;
ALTER TABLE public.site_content ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_content ON public.site_content FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY admin_content ON public.site_content FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE POLICY website_image_read ON storage.objects FOR SELECT TO anon,authenticated USING(bucket_id='website-images');
CREATE POLICY website_image_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='website-images' AND public.has_role(auth.uid(),'admin'));
CREATE POLICY website_image_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='website-images' AND public.has_role(auth.uid(),'admin'));
REVOKE ALL ON FUNCTION public.assign_cms_admin() FROM PUBLIC;